-- 확인: 직군별 회원 수 합이 위 머리말의 회원 수와 같으면 정상
SELECT A.WORKER_TYPE_CODE, COUNT(DISTINCT A.USER_ID) AS 회원 FROM ASSESSMENT A JOIN APP_USER U ON U.USER_ID = A.USER_ID WHERE U.DUMMY_YN = 'Y' AND A.MODEL_VERSION = 'LGBM-BASE-0.2' AND A.GRADE_STATUS_CODE = 'SCORED' GROUP BY A.WORKER_TYPE_CODE ORDER BY 1;
